using Microsoft.EntityFrameworkCore;
class ProductContext : DbContext
{
    public DbSet<Product> Products => Set<Product>();
    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        modelBuilder.Entity<Product>(entity =>
        {
            entity.ToContainer("Products");

            // EF Core 9 breaking change #1: Discriminator property renamed from
            // "Discriminator" to "$type". Existing 500K documents use "Discriminator",
            // so we must preserve the old property name for data compatibility.
            entity.HasDiscriminator<string>("Discriminator");

            // EF Core 9 breaking change #2: Id format changed from "EntityType|Key"
            // (e.g. "Product|123") to just the raw key value ("123"). Existing documents
            // use the prefixed format, so we must opt in to the legacy id format.
            entity.HasPartitionKey(p => p.Id);
            entity.Property(p => p.Id)
                  .ToJsonProperty("id")
                  .HasValueGenerator<Microsoft.EntityFrameworkCore.Cosmos.ValueGeneration.Internal.IdValueGenerator>();
        });

        // EF Core 9 breaking change #1 (continued): Keep the legacy "Discriminator"
        // property name for all entity types so direct SQL queries referencing
        // c.Discriminator continue to work.
        // Already handled per-entity above; this comment documents the global concern.
    }

    protected override void ConfigureConventions(ModelConfigurationBuilder configurationBuilder)
    {
        // Preserve the EF Core 8 id format "EntityType|KeyValue" for all entities.
        // Without this, EF Core 9 generates bare key values and cannot find existing docs.
        configurationBuilder.Conventions.Add(_ =>
            new Microsoft.EntityFrameworkCore.Cosmos.Metadata.Conventions.CosmosNoIdValueGeneratorConvention());
    }
}
class Product { public int Id { get; set; } public string Sku { get; set; } }

