class CosmosQuery
{
    void FindProducts(ProductContext ctx)
    {
        // Direct Cosmos SQL
        var sql = "SELECT * FROM c WHERE c.Discriminator = 'Product' AND c.Sku = @sku";
        // Also uses sync APIs
        var products = ctx.Products.Where(p => p.Sku == "ABC").ToList();
    }
}

arguments.new_str:
class CosmosQuery
{
    // EF Core 9 breaking change #3: Synchronous I/O APIs (ToList, First, Single, etc.)
    // now throw InvalidOperationException on the Cosmos provider. All queries must be async.
    async Task FindProducts(ProductContext ctx)
    {
        // Direct Cosmos SQL — works because we preserved "Discriminator" property name
        // in OnModelCreating via HasDiscriminator<string>("Discriminator").
        var sql = "SELECT * FROM c WHERE c.Discriminator = 'Product' AND c.Sku = @sku";

        // Converted from sync ToList() to async ToListAsync()
        var products = await ctx.Products.Where(p => p.Sku == "ABC").ToListAsync();
    }
}

