using Microsoft.EntityFrameworkCore;
class ProductContext : DbContext
{
    public DbSet<Product> Products => Set<Product>();
    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        modelBuilder.Entity<Product>(entity =>
        {
            entity.ToContainer("Products");

            // BREAKING CHANGE #1 — Discriminator property renamed.
            // EF Core 9 writes "$type" instead of "Discriminator". Existing 500K
            // documents (and direct SQL queries like c.Discriminator = 'Product')
            // depend on the old name, so we pin it explicitly.
            entity.HasDiscriminator<string>("Discriminator");

            // BREAKING CHANGE #2 — Id format changed.
            // EF Core 8 stored id as "Product|123"; EF Core 9 stores just "123".
            // Existing documents use the prefixed format. We preserve it by
            // mapping a shadow __id property with a value-generated id that
            // includes the entity type name.
            entity.Property<string>("__id")
                  .ToJsonProperty("id");
            entity.HasKey("__id");
        });

        // BREAKING CHANGE #4 — HasIndex now throws on Cosmos provider.
        // The HasIndex(p => p.Sku) call from EF Core 8 was silently ignored;
        // in EF Core 9 it throws. Removed. Cosmos indexes are managed via
        // the container's indexing policy in the Azure portal / ARM templates.
    }
}
