1. using Microsoft.EntityFrameworkCore;
2. class ProductContext : DbContext
3. {
4.     public DbSet<Product> Products => Set<Product>();
5.     protected override void OnModelCreating(ModelBuilder modelBuilder)
6.     {
7.         modelBuilder.Entity<Product>(entity =>
8.         {
9.             entity.ToContainer("Products");
10. 
11.             // BREAKING CHANGE #1 — Discriminator property renamed.
12.             // EF Core 9 writes "$type" instead of "Discriminator". Existing 500K
13.             // documents (and direct SQL queries like c.Discriminator = 'Product')
14.             // depend on the old name, so we pin it explicitly.
15.             entity.HasDiscriminator<string>("Discriminator");
16. 
17.             // BREAKING CHANGE #2 — Id format changed.
18.             // EF Core 8 stored id as "Product|123"; EF Core 9 stores just "123".
19.             // Existing documents use the prefixed format. We preserve it by
20.             // mapping a shadow __id property with a value-generated id that
21.             // includes the entity type name.
22.             entity.Property<string>("__id")
23.                   .ToJsonProperty("id");
24.             entity.HasKey("__id");
25.         });
26. 
27.         // BREAKING CHANGE #4 — HasIndex now throws on Cosmos provider.
28.         // The HasIndex(p => p.Sku) call from EF Core 8 was silently ignored;
29.         // in EF Core 9 it throws. Removed. Cosmos indexes are managed via
30.         // the container's indexing policy in the Azure portal / ARM templates.
31.     }
32. }
33. class Product { public int Id { get; set; } public string Sku { get; set; } }
